import numpy as np
for n in (1, 2, 4, 16):
    w = walsh(n)
    assert w.shape == (n, n) and set(np.unique(w)) <= {-1, 1}
    assert np.array_equal(w @ w.T, n * np.eye(n)), f"rows of walsh({n}) must be orthogonal"
assert np.array_equal(walsh(2), np.array([[1, 1], [1, -1]]))
rng = np.random.default_rng(0)
W = walsh(16)
bits = {u: rng.choice([-1, 1], 40) for u in (3, 7, 12)}
gain = {3: 1.0, 7: 3.0, 12: 0.3}
air = sum(gain[u] * np.kron(bits[u], W[u]) for u in bits) + rng.normal(0, 0.3, 40 * 16)
for u in bits:
    out = despread(air, W[u])
    assert out.shape == (40,), "one decision per bit"
    assert np.array_equal(out, bits[u]), f"user {u} was not recovered"

